"""Prepare generic QX scripts before publishing any synchronized configuration.

Upstream JavaScript is preserved verbatim inside a shared API facade. Validation
uses Node's parser only; synchronization never executes third-party scripts.
"""
from __future__ import annotations

import hashlib
import json
from pathlib import Path
import re
import subprocess
from urllib.parse import urlsplit

from _common import write_if_changed
from qx_convert import convert_qx_module, is_qx_module


OWNERS_FILE = ".github/scripts/qx-scripts-owned.json"
GENERATED_HEADER = "// Generated by .github/scripts/qx_scripts.py; do not edit."
SCRIPT_DIRECTORY = "Surge/Module/Scripts"
RAW_SCRIPT_BASE = "https://raw.githubusercontent.com/HotKids/Rules/refs/heads/master/" + SCRIPT_DIRECTORY + "/"
_MODES = {"request", "request-body", "response", "response-body", "echo", "cron"}
_OWNED_NAME = re.compile(r"Surge/Module/Scripts/qx-[0-9a-f]{64}\.js")


def _digest(value):
    return hashlib.sha256(value.encode("utf-8")).hexdigest()


def _safe_path(root, relative):
    path = root / relative
    if path.is_symlink() or not path.resolve().is_relative_to(root.resolve()):
        raise ValueError("Unsafe QX generated-script path")
    return path


def _read_owners(root):
    path = _safe_path(root, OWNERS_FILE)
    if not path.exists():
        return {}
    state = json.loads(path.read_text(encoding="utf-8"))
    if (not isinstance(state, dict) or state.get("version") != 1
            or not isinstance(state.get("files"), dict)):
        raise ValueError("Invalid QX script ownership record")
    files = state["files"]
    if any(not isinstance(name, str) or not _OWNED_NAME.fullmatch(name)
           or not isinstance(digest, str) or not re.fullmatch(r"[0-9a-f]{64}", digest)
           for name, digest in files.items()):
        raise ValueError("Invalid QX script ownership path or fingerprint")
    return dict(files)


def _owned_content(path, digest):
    if not path.is_file():
        return False
    content = path.read_bytes()
    return (hashlib.sha256(content).hexdigest() == digest
            and content.startswith((GENERATED_HEADER + "\n").encode("utf-8")))


def _wrap_script(source, runtime, url, mode):
    namespace = "qx-" + _digest(url)
    # Facade bindings live outside the original source's function scope. This
    # preserves its directives and local declarations, including `module`/Env
    # shims, without changing its $argument or patching any application code.
    return (GENERATED_HEADER + "\n"
            + "(function (native) {\n" + runtime.rstrip() + "\n"
            + "const bridge = createQxRuntime(native, " + json.dumps(mode)
            + ", " + json.dumps(namespace) + ");\n"
            + "return (function ($request, $response, $prefs, $notify, $task, $done) {\n"
            + "return (function () {\n// BEGIN UPSTREAM SOURCE\n" + source
            + "\n// END UPSTREAM SOURCE\n}).call(this);\n"
            + "}).call(this, bridge.request, bridge.response, bridge.prefs, bridge.notify, bridge.task, bridge.done);\n"
            + "})({\n"
            + "request: typeof $request === 'undefined' ? undefined : $request,\n"
            + "response: typeof $response === 'undefined' ? undefined : $response,\n"
            + "persistentStore: typeof $persistentStore === 'undefined' ? undefined : $persistentStore,\n"
            + "notification: typeof $notification === 'undefined' ? undefined : $notification,\n"
            + "httpClient: typeof $httpClient === 'undefined' ? undefined : $httpClient,\n"
            + "done: typeof $done === 'undefined' ? undefined : $done,\n"
            + "platform: typeof $environment !== 'undefined' && ($environment['stash-version'] || $environment['stash-build']) ? 'stash' : 'surge'\n"
            + "});\n")


def _validate_script(content, identifier):
    try:
        result = subprocess.run(["node", "--check"], input=content, text=True,
                                capture_output=True, timeout=30)
    except (OSError, subprocess.TimeoutExpired):
        raise RuntimeError("QX script syntax validation requires a working Node.js parser") from None
    if result.returncode:
        # Parser stderr includes source lines; never repeat credentials, response
        # examples or query strings from an upstream script in public CI logs.
        raise ValueError(f"QX script syntax validation failed: {identifier}")


class PreparedQxModules:
    def __init__(self, root, sources, converted, scripts, owners):
        self.root = root.resolve()
        self.sources = {url: _digest(body) for url, body in sources.items()}
        self.converted = converted
        self.scripts = scripts
        self.owners = owners

    def validate_inputs(self, root, entries, prefetched):
        sources = {entry["url"]: prefetched.get(entry["url"]) or "" for entry in entries}
        if (root.resolve() != self.root
                or {url: _digest(body) for url, body in sources.items()} != self.sources):
            raise ValueError("Prepared QX script batch does not match module sources")

    def validate_destinations(self):
        # Reject conflicting edits for the complete batch before writing even
        # the first script. Unknown files may only be adopted when byte-equal.
        for relative in self.owners:
            _safe_path(self.root, relative)
        for relative, content in self.scripts.items():
            path = _safe_path(self.root, relative)
            if path.exists() and path.read_bytes() != content.encode("utf-8"):
                if relative not in self.owners or not _owned_content(path, self.owners[relative]):
                    raise ValueError(f"Generated QX script has local edits; refusing to overwrite: {relative}")

    def write_scripts(self):
        self.validate_destinations()
        for relative, content in self.scripts.items():
            write_if_changed(_safe_path(self.root, relative), content)

    def finish(self):
        """Clean only fingerprinted, unedited wrappers after modules are written."""
        for relative, digest in self.owners.items():
            if relative in self.scripts:
                continue
            path = _safe_path(self.root, relative)
            if path.exists() and _owned_content(path, digest):
                path.unlink()
            elif path.exists():
                print(f"  [WARN] {relative} 已手动修改，保留并解除 QX 自动清理归属")
        files = {name: _digest(content) for name, content in sorted(self.scripts.items())}
        if files or self.owners or (self.root / OWNERS_FILE).exists():
            state = {"version": 1, "files": files}
            write_if_changed(_safe_path(self.root, OWNERS_FILE),
                             json.dumps(state, ensure_ascii=False, indent=2) + "\n")


def prepare_qx_modules(entries, prefetched, root, download_scripts):
    """Convert QX configs, fetch all referenced JS, and parse every wrapper.

    The returned plan performs no filesystem changes until explicitly committed.
    Native Surge modules pass through without fetching or wrapping their scripts.
    """
    root = Path(root)
    sources = {entry["url"]: prefetched.get(entry["url"]) or "" for entry in entries}
    converted, references = {}, {}

    def script_url(url, mode):
        if mode not in _MODES:
            raise ValueError("Unsupported QX script execution mode")
        identifier = "qx-" + _digest(url + "\0" + mode) + ".js"
        references.setdefault((url, mode), identifier)
        return RAW_SCRIPT_BASE + identifier

    for url, text in sources.items():
        if urlsplit(url).path.lower().endswith(".snippet") or is_qx_module(text):
            converted[url] = convert_qx_module(text, script_url=script_url,
                                              script_prefix="qx-" + _digest(url)[:12])

    scripts = {}
    if references:
        urls = list(dict.fromkeys(url for url, _mode in references))
        bodies = download_scripts(urls)
        runtime = Path(__file__).with_name("qx-runtime.js").read_text(encoding="utf-8")
        for (url, mode), identifier in references.items():
            body = bodies.get(url)
            if not isinstance(body, str) or not body.strip() or "\0" in body:
                raise ValueError(f"QX script download is empty or invalid: {identifier}")
            if re.match(r"\s*(?:<!doctype\s+html|<html\b)", body, re.I):
                raise ValueError(f"QX script download returned HTML: {identifier}")
            content = _wrap_script(body, runtime, url, mode)
            _validate_script(content, identifier)
            scripts[SCRIPT_DIRECTORY + "/" + identifier] = content
    owners = _read_owners(root)
    batch = PreparedQxModules(root, sources, converted, scripts, owners)
    # Ownership/path conflicts are errors before any rules or modules are written.
    batch.validate_destinations()
    return batch
